func TestManagerCreatesDiffsAndRemovesWorktree(t *testing.T) {
	root := t.TempDir()
	runGit(t, root, "init")
	runGit(t, root, "config", "user.email", "test@example.com")
	runGit(t, root, "config", "user.name", "Test User")

	if err := os.WriteFile(filepath.Join(root, "README.md"), []byte("hello\n"), 0o644); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	runGit(t, root, "add", "README.md")
	runGit(t, root, "commit", "-m", "init")

	manager := Manager{
		Root:    root,
		Scratch: t.TempDir(),
		Prefix:  "codex/test",
	}

	checkout, err := manager.Create(context.Background(), "Refactor App.go!")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	if checkout.Name != "refactor-app-go" || !strings.HasPrefix(checkout.Branch, "codex/test/refactor-app-go-") {
		t.Fatalf("unexpected checkout identity: %#v", checkout)
	}

	if _, err := os.Stat(filepath.Join(checkout.Path, "README.md")); err != nil {
		t.Fatalf("expected worktree checkout: %v", err)
	}

	if err := os.WriteFile(filepath.Join(checkout.Path, "README.md"), []byte("hello\nworld\n"), 0o644); err != nil {
		t.Fatalf("write worktree file: %v", err)
	}

	diff, err := manager.Diff(context.Background(), checkout)
	if err != nil {
		t.Fatalf("Diff: %v", err)
	}

	if len(diff.ChangedPaths) != 1 || diff.ChangedPaths[0] != "README.md" {
		t.Fatalf("unexpected changed paths: %#v", diff)
	}

	if diff.Stat == "" {
		t.Fatalf("expected diff stat")
	}

	if !strings.Contains(diff.Patch, "+world") {
		t.Fatalf("expected binary patch to include changed file contents, got:\n%s", diff.Patch)
	}

	if err := manager.Remove(context.Background(), checkout); err != nil {
		t.Fatalf("Remove: %v", err)
	}

	if _, err := os.Stat(checkout.Path); !os.IsNotExist(err) {
		t.Fatalf("expected worktree path removed, stat err=%v", err)
	}

	if branches := runGitOutput(t, root, "branch", "--list", checkout.Branch); strings.TrimSpace(branches) != "" {
		t.Fatalf("expected temporary branch removed, got %q", branches)
	}

	second, err := manager.Create(context.Background(), "Refactor App.go!")
	if err != nil {
		t.Fatalf("Create with same logical name after cleanup: %v", err)
	}

	if second.Branch == checkout.Branch || second.Path == checkout.Path {
		t.Fatalf("expected unique branch and path after repeated create, first=%#v second=%#v", checkout, second)
	}

	if err := manager.Remove(context.Background(), second); err != nil {
		t.Fatalf("Remove second checkout: %v", err)
	}
}

func TestDiffIncludesUntrackedFiles(t *testing.T) {
	root := t.TempDir()
	runGit(t, root, "init")
	runGit(t, root, "config", "user.email", "test@example.com")
	runGit(t, root, "config", "user.name", "Test User")

	if err := os.WriteFile(filepath.Join(root, "README.md"), []byte("hello\n"), 0o644); err != nil {
		t.Fatalf("write seed file: %v", err)
	}

	runGit(t, root, "add", "README.md")
	runGit(t, root, "commit", "-m", "init")

	manager := Manager{
		Root:    root,
		Scratch: t.TempDir(),
		Prefix:  "codex/test",
	}

	checkout, err := manager.Create(context.Background(), "new-file")
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	defer func() {
		if err := manager.Remove(context.Background(), checkout); err != nil {
			t.Fatalf("Remove: %v", err)
		}
	}()

	if err := os.WriteFile(filepath.Join(checkout.Path, "NEW.md"), []byte("new file\n"), 0o644); err != nil {
		t.Fatalf("write untracked file: %v", err)
	}

	diff, err := manager.Diff(context.Background(), checkout)
	if err != nil {
		t.Fatalf("Diff: %v", err)
	}

	if len(diff.ChangedPaths) != 1 || diff.ChangedPaths[0] != "NEW.md" {
		t.Fatalf("expected untracked file in changed paths, got %#v", diff.ChangedPaths)
	}

	if !strings.Contains(diff.Patch, "new file mode") || !strings.Contains(diff.Patch, "+new file") {
		t.Fatalf("expected untracked file patch, got:\n%s", diff.Patch)
	}
}

func runGit(t *testing.T, root string, args ...string) {
	t.Helper()

	_ = runGitOutput(t, root, args...)
}

func runGitOutput(t *testing.T, root string, args ...string) string {
	t.Helper()

	cmd := exec.Command("git", append([]string{"-C", root}, args...)...)

	output, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, output)
	}

	return string(output)
}

func TestToolResultEvidenceProjectionUsesTypedReadPathsNotMentionRelationships(t *testing.T) {
	result := workspace.ToolResult{
		Tool:          " read_file ",
		Code:          "ok",
		Summary:       ` Read ./internal\runtime\agent\runner_core.go lines 1-20 `,
		Output:        "Read internal/runtime/agent/runner_core.go lines 1-20\npackage main",
		PrecisionTier: "source_body",
		Relationships: []workspace.ToolRelationship{
			{Kind: "reads", SourcePath: "./internal/runtime/agent/runner_core.go"},
			{Kind: "mentions", TargetPath: "internal\\runtime\\agent\\evidence_registry.go"},
			{Kind: "reads", SourcePath: "internal/runtime/agent/runner_core.go"},
		},
	}

	projection := newToolResultEvidenceProjection([]workspace.ToolResult{result})
	if !projection.HasSourceBody("internal/runtime/agent/runner_core.go") {
		t.Fatal("expected typed read path to count as source-body evidence")
	}
	if projection.HasSourceBody("internal/runtime/agent/evidence_registry.go") {
		t.Fatal("mention-only relationship must not count as source-body evidence")
	}
}

func TestFailedReadFileMissingPathIsNotAcceptedEvidence(t *testing.T) {
	const (
		missingPath   = "internal/runtime/agent/missing.go"
		inspectedPath = "internal/runtime/agent/runner_core.go"
	)

	results := []workspace.ToolResult{
		{
			Tool:    "read_file",
			Summary: "Read internal/runtime/agent/missing.go lines 1-80",
			Error:   "internal/runtime/agent/missing.go was not found",
		},
		{
			Tool:    "search_content",
			Summary: "No matches in internal/runtime/agent/zero_hit.go",
			Output:  "0 matching line(s)",
		},
		{
			Tool:    "read_file",
			Summary: "Read internal/runtime/agent/runner_core.go lines 1-8",
			Output:  "package agent\n\nfunc evidenceTelemetryRegressionFixture() {}\n",
		},
	}

	for name, paths := range map[string][]string{
		"direct probes":           directProbePathsFromToolResults(results, 8),
		"mentioned evidence":      mentionedEvidencePathsFromToolResults(results, 8),
		"implementation evidence": acceptedImplementationEvidencePaths(results),
	} {
		if slices.Contains(paths, missingPath) {
			t.Fatalf("%s promoted missing read_file path as accepted evidence: %#v", name, paths)
		}

		if slices.Contains(paths, "internal/runtime/agent/zero_hit.go") {
			t.Fatalf("%s promoted zero-hit search path as accepted evidence: %#v", name, paths)
		}

		if !slices.Contains(paths, inspectedPath) {
			t.Fatalf("%s should preserve successful read_file evidence path %q, got %#v", name, inspectedPath, paths)
		}
	}
}

func TestModelCallTelemetryDistinguishesParsedTextualTool(t *testing.T) {
	var event RunEvent

	runner := &Runner{
		OnEvent: func(got RunEvent) {
			event = got
		},
	}

	runner.emitModelCallTraceWithOptions(
		1,
		"regression",
		[]llama.ChatMessage{{Role: "user", Content: "inspect runner"}},
		llama.ChatMessage{
			Role:    "assistant",
			Content: `{"tool":"read_file","path":"internal/runtime/agent/runner_core.go"}`,
		},
		7,
		llama.ChatOptions{},
		false,
		nil,
	)

	if event.Role != "model_call" {
		t.Fatalf("expected model_call event, got %#v", event)
	}

	var payload map[string]any

	if err := json.Unmarshal([]byte(event.Content), &payload); err != nil {
		t.Fatalf("decode model_call payload: %v", err)
	}

	if payload["chosen_tool"] != "<answer>" {
		t.Fatalf("textual tool request must not masquerade as native chosen_tool, got %#v", payload)
	}

	if payload["parsed_textual_tool"] != "read_file" {
		t.Fatalf("model_call telemetry missing parsed textual tool identity: %#v", payload)
	}

	if payload["parsed_tool_transport"] != "textual" {
		t.Fatalf("model_call telemetry missing textual transport: %#v", payload)
	}

	if payload["parsed_tool_request_valid"] != true {
		t.Fatalf("model_call telemetry should mark parsed textual request valid: %#v", payload)
	}
}

