func TestReadOnlyPrefetchEvidenceDedupsWithModelReadAndKeepsSource(t *testing.T) {
	brief := readOnlyConversationBriefForTest("Read README.md and explain what Idiom is.")
	results := []workspace.ToolResult{
		{
			Tool:    workspace.ToolNamePrefetch,
			Summary: "Read f1 README.md lines 1-1 (total lines: 1; source: prefetch)",
			Output:  "1:Idiom is a local coding-agent harness.\n",
		},
		{
			Tool:    "read_file",
			Summary: "Read f1 README.md lines 1-1 (total lines: 1)",
			Output:  "1:Idiom is a local coding-agent harness.\n",
		},
	}

	ledger := readOnlyAnswerabilityForResults(brief, results)
	if got := ledger.SourceBodyPaths; !slices.Equal(got, []string{"README.md"}) {
		t.Fatalf("expected deduped source body paths, got %#v", got)
	}

	var (
		prefetchItems int
		readItems     int
	)

	for _, item := range ledger.Items {
		if item.Kind != readOnlyEvidenceSourceBody || item.Path != "README.md" {
			continue
		}

		switch item.Source {
		case "prefetch":
			prefetchItems++
		case "read_file":
			readItems++
		}
	}

	if prefetchItems != 1 || readItems != 1 {
		t.Fatalf("expected distinct source attribution for prefetch/read_file, got prefetch=%d read=%d items=%#v", prefetchItems, readItems, ledger.Items)
	}
}

func TestReadOnlySourceBodyEvidenceSummary(t *testing.T) {
	bodyPath := "internal/runtime/agent/runner_core.go"
	candidatePath := "internal/surfaces/tui/app/rendering.go"

	// Ensure candidate test paths exist on filesystem for Fix 7 (candidate path verification).
	// The paths are relative to the workspace root; create minimal temp structures.
	candidateDir := filepath.Dir(candidatePath)
	if err := os.MkdirAll(candidateDir, 0755); err == nil {
		os.WriteFile(candidatePath, []byte("package app\nfunc Render() {}\n"), 0644)
		os.WriteFile("internal/surfaces/tui/app/panel.go", []byte("package app\ntype Panel struct{}\n"), 0644)
		defer func() {
			os.RemoveAll("internal/surfaces")
		}()
	}

	results := []workspace.ToolResult{
		{
			Tool:    "read_file",
			Summary: "Read " + bodyPath + " lines 1-20",
			Output:  "package agent\nfunc Run() {}\n",
		},
		{
			Tool:    "search_content",
			Summary: "Found 5 matching line(s).",
			Output:  candidatePath + ":42: func Render() {}",
		},
		{
			Tool:    "search_content",
			Summary: "Found 3 more candidates",
			Output:  "internal/surfaces/tui/app/model_state.go:10: type Model struct{}",
		},
	}

	t.Run("body-and-candidate", func(t *testing.T) {
		summary := readOnlySourceBodyEvidenceSummary(results)
		if summary == "" {
			t.Fatal("expected non-empty summary")
		}

		if !strings.Contains(summary, bodyPath) {
			t.Fatalf("expected body path %q in summary, got: %s", bodyPath, summary)
		}

		if !strings.Contains(summary, "Source-body evidence available") {
			t.Fatalf("expected body evidence header in summary, got: %s", summary)
		}

		if !strings.Contains(summary, candidatePath) {
			t.Fatalf("expected candidate path %q in summary, got: %s", candidatePath, summary)
		}

		if !strings.Contains(summary, "Candidate paths") {
			t.Fatalf("expected candidate paths header in summary, got: %s", summary)
		}

		if !strings.Contains(summary, "cite only the body-backed paths") {
			t.Fatalf("expected guidance in summary, got: %s", summary)
		}
	})

	t.Run("no-candidates", func(t *testing.T) {
		bodyOnly := []workspace.ToolResult{
			{
				Tool:    "read_file",
				Summary: "Read " + bodyPath + " lines 1-20",
				Output:  "package agent\nfunc Run() {}\n",
			},
		}
		summary := readOnlySourceBodyEvidenceSummary(bodyOnly)
		if summary == "" {
			t.Fatal("expected non-empty summary for body-only")
		}

		if !strings.Contains(summary, bodyPath) {
			t.Fatalf("expected body path in summary, got: %s", summary)
		}

		if strings.Contains(summary, "Candidate paths") {
			t.Fatalf("expected no candidate section for body-only, got: %s", summary)
		}
	})

	t.Run("no-body", func(t *testing.T) {
		candidateOnly := []workspace.ToolResult{
			{
				Tool:    "search_content",
				Summary: "Found 2 matching line(s).",
				Output:  "internal/surfaces/tui/app/panel.go:5: type Panel struct{}",
			},
		}
		summary := readOnlySourceBodyEvidenceSummary(candidateOnly)
		if summary == "" {
			t.Fatal("expected non-empty summary for candidate-only")
		}

		if !strings.Contains(summary, "Candidate paths") {
			t.Fatalf("expected candidate section, got: %s", summary)
		}

		if strings.Contains(summary, "Source-body evidence available") {
			t.Fatalf("expected no body section for candidate-only, got: %s", summary)
		}
	})

	t.Run("empty-results", func(t *testing.T) {
		summary := readOnlySourceBodyEvidenceSummary(nil)
		if summary != "" {
			t.Fatalf("expected empty summary for nil results, got: %s", summary)
		}
	})

	t.Run("body-path-not-in-candidate", func(t *testing.T) {
		summary := readOnlySourceBodyEvidenceSummary(results)
		// The body path must not appear in the candidate section
		if strings.Contains(summary, "Candidate paths") {
			parts := strings.Split(summary, "Candidate paths")
			if len(parts) > 1 && strings.Contains(parts[1], bodyPath) {
				t.Fatalf("body path %q must not appear in candidate section, summary: %s", bodyPath, summary)
			}
		}
	})
}

func TestReadOnlyCloseoutRejectsLowValueSourceInventoryAcrossConsumers(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:        "conversation",
		Contract:          "direct_answer",
		PermissionProfile: "read_only_workspace",
		Objective:         "what would it take to enable up and down arrow keys to iterate through the user's chat history?",
	}
	results := []workspace.ToolResult{{
		Tool:    "read_file",
		Summary: "Read internal/surfaces/tui/app/app.go lines 1-8",
		Output: strings.Join([]string{
			"1:package app",
			"2:",
			"3:func truncateText(value string, max int) string {",
			"4:\treturn value",
			"5:}",
			"6:func normalizeHistoryRole(value string) string {",
			"7:\treturn strings.ToUpper(value[:1]) + value[1:]",
			"8:}",
		}, "\n"),
	}}
	answer := "For `what would it take to enable up and down arrow keys to iterate through the user's chat history?`, `internal/surfaces/tui/app/app.go` shows defines `truncateText`, defines `normalizeHistoryRole`, and `normalizeHistoryRole` returns `strings.ToUpper(value[:1]) + value[1:]`."

	closeout := readOnlyClosureDecisionForResults(brief, results)
	if closeout.AllowsSourceInventoryAnswer(answer, true) {
		t.Fatal("closeout contract must not allow low-value source inventory as an accepted answer")
	}

	runner := &Runner{RuntimeBrief: brief}
	acceptance := runner.evaluateFinalAnswerAcceptance(answer, results)

	if acceptance.Decision != finalAnswerAcceptanceRejected {
		t.Fatalf("acceptance should reject low-value source inventory through closeout contract: %#v", acceptance)
	}

	presented, ok := closeout.PresentableFallbackCandidate("main", answer)
	if !ok {
		t.Fatal("expected closeout contract to provide a user-facing replacement")
	}

	for _, forbidden := range []string{"truncateText", "normalizeHistoryRole"} {
		if strings.Contains(presented, forbidden) {
			t.Fatalf("replacement leaked low-value source inventory %q:\n%s", forbidden, presented)
		}
	}

	if !strings.Contains(presented, "I do not have a supported answer") {
		t.Fatalf("replacement should be an evidence-bounded uncertainty answer:\n%s", presented)
	}
}

