func TestObligationResolutionAttemptsCountsOnlyNavigationFailures(t *testing.T) {
	results := []workspace.ToolResult{
		// Successful code_navigate — not counted.
		{
			Tool:    "code_navigate",
			Summary: "Code navigation routed read_symbol via go_read_symbol",
			Output:  "internal/surfaces/tui/app/sessions.go",
		},
		// Failed code_navigate — counted.
		{
			Tool:    "code_navigate",
			Summary: "No generic code navigation matches",
			Error:   "no symbolic match",
			Output:  "internal/surfaces/tui/app/sessions.go",
		},
		// read_file on the path — not code_navigate, not counted.
		{
			Tool:    "read_file",
			Summary: "Read f1 internal/surfaces/tui/app/sessions.go",
			Output:  "internal/surfaces/tui/app/sessions.go",
		},
		// code_navigate on a different path — not counted.
		{
			Tool:    "code_navigate",
			Summary: "No generic code navigation matches",
			Error:   "no matches",
			Output:  "internal/surfaces/tui/app/other.go",
		},
	}
	attempts := sourceEvidenceObligationResolutionAttempts("internal/surfaces/tui/app/sessions.go", results)

	if attempts != 1 {
		t.Fatalf("resolution attempts = %d, want 1 (only the one failed code_navigate on the path should count)", attempts)
	}
}

func TestSourceEvidenceStateTracksRedirectPendingUntilBodyEvidence(t *testing.T) {
	results := []workspace.ToolResult{
		{
			Tool:    "read_file",
			Summary: "Redirected internal/surfaces/tui/app/sessions.go to code_navigate",
			Output:  "Use code_navigate for source-body evidence in internal/surfaces/tui/app/sessions.go.",
		},
	}

	evidence := newToolResultEvidenceProjection(results).SourceEvidenceForPath("internal/surfaces/tui/app/sessions.go")
	if evidence.Level != planThenExecuteEvidenceSourceBodyPending {
		t.Fatalf("Level = %q, want %q", evidence.Level, planThenExecuteEvidenceSourceBodyPending)
	}

	if newToolResultEvidenceProjection(results).HasSourceBody("internal/surfaces/tui/app/sessions.go") {
		t.Fatal("redirect-only evidence must not count as source-body evidence")
	}

	req := workspace.ToolRequest{Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions.go", Capability: "read_symbol", Pattern: "session"}
	pending := sourceEvidencePendingRedirects(results)
	if len(pending) != 1 {
		t.Fatalf("pending redirects = %#v, want one sessions.go obligation", pending)
	}
	if !sourceEvidencePendingRedirectRequestAllowed(pending[0], req) {
		t.Fatal("exact redirected source-body follow-up should be allowed")
	}

	for name, badReq := range map[string]workspace.ToolRequest{
		"missing source-body capability": {Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions.go"},
		"file outline":                   {Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions.go", Capability: "file_outline"},
		"references":                     {Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions.go", Capability: "references", Pattern: "session"},
		"read symbol missing pattern":    {Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions.go", Capability: "read_symbol"},
	} {
		if sourceEvidencePendingRedirectRequestAllowed(pending[0], badReq) {
			t.Fatalf("%s should not satisfy a redirected source-body obligation", name)
		}
	}

	other := workspace.ToolRequest{Tool: "code_navigate", Path: "internal/surfaces/tui/app/sessions_panel.go", Capability: "read_symbol", Pattern: "session"}
	if NormalizeRunnerPath(other.Path) == pending[0].Path && sourceEvidencePendingRedirectRequestAllowed(pending[0], other) {
		t.Fatal("redirect follow-up allowance must stay scoped to the redirected path")
	}

	results = append(results, workspace.ToolResult{
		Tool: "code_navigate",
		Output: "route_summary: Read internal/surfaces/tui/app/sessions.go lines 10-40 (total lines: 120)\n" +
			"func (m sessionModel) moveDown() {\n\tm.cursor++\n}\n",
	})
	evidence = newToolResultEvidenceProjection(results).SourceEvidenceForPath("internal/surfaces/tui/app/sessions.go")

	if !sourceEvidenceHasBody(evidence) {
		t.Fatalf("Level = %q, want source-body evidence after routed body read", evidence.Level)
	}

	if pending := sourceEvidencePendingRedirects(results); len(pending) != 0 {
		t.Fatalf("pending redirects after body evidence = %#v, want none", pending)
	}
}

func TestRedirectOnlyEvidenceDoesNotBecomeSourceSatisfiedAnchorReady(t *testing.T) {
	results := []workspace.ToolResult{
		{
			Tool:    "read_file",
			Summary: "Redirected internal/surfaces/tui/app/sessions.go to code_navigate",
			Output:  "Use code_navigate for source-body evidence in internal/surfaces/tui/app/sessions.go.",
		},
	}

	evidence := planThenExecuteObservedSourceEvidenceForPath(results, "internal/surfaces/tui/app/sessions.go")
	if evidence.Level != planThenExecuteEvidenceSourceBodyPending {
		t.Fatalf("Level = %q, want %q", evidence.Level, planThenExecuteEvidenceSourceBodyPending)
	}

	if planThenExecuteEvidenceRank(evidence.Level) >= planThenExecuteEvidenceRank(planThenExecuteEvidenceAnchorReady) {
		t.Fatalf("redirect-only evidence must not satisfy source_satisfied_paths anchor threshold: %#v", evidence)
	}
}

