func TestSourceEvidenceNonBodySignalsDoNotCloseSourceBodyObligations(t *testing.T) {
	cases := []struct {
		name   string
		result workspace.ToolResult
	}{
		{
			name: "search hit",
			result: workspace.ToolResult{
				Tool:    "search_content",
				Summary: "Found 1 matching line(s) in internal/runtime/agent/runner_core.go.",
				Output:  "internal/runtime/agent/runner_core.go:88: func (r *Runner) Run(...)",
			},
		},
		{
			name: "context packet",
			result: workspace.ToolResult{
				Tool:    "context_pack",
				Summary: "Context pack includes internal/runtime/agent/runner_core.go.",
				Facts:   contextPackCandidateFactsForTest("internal/runtime/agent/runner_core.go"),
			},
		},
		{
			name: "diagnostic",
			result: workspace.ToolResult{
				Tool:    "source_sanity",
				Summary: "source_sanity failed for internal/runtime/agent/runner_core.go",
				Output:  "internal/runtime/agent/runner_core.go:88: undefined: runState",
			},
		},
		{
			name: "log summary",
			result: workspace.ToolResult{
				Tool:    "read_file",
				Summary: "Read logs/conversations/session.jsonl lines 1-20",
				Output:  `{"message":"model mentioned internal/runtime/agent/runner_core.go"}`,
			},
		},
		{
			name: "plain mentioned path",
			result: workspace.ToolResult{
				Tool:    "task",
				Summary: "Child task completed",
				Output:  "Mentioned paths: internal/runtime/agent/runner_core.go",
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			results := []workspace.ToolResult{tc.result}
			if newToolResultEvidenceProjection(results).HasSourceBody("internal/runtime/agent/runner_core.go") {
				t.Fatalf("%s must not satisfy source-body evidence", tc.name)
			}

			if paths := newToolResultEvidenceProjection(results).SourceBodyPaths(); len(paths) != 0 {
				t.Fatalf("%s produced source-body paths: %#v", tc.name, paths)
			}
		})
	}
}

