func TestPlanExecuteRecoveryStateProjectsMalformedSubmitPlanRecoveryPhase(t *testing.T) {
	brief := workerruntime.WorkerRuntimeBrief{
		TaskFamily:        PlanThenExecutePlannerTaskFamily,
		Contract:          "implementation_result",
		PermissionProfile: "guarded_workspace_write",
		AllowedTools:      []string{"read_file", workspace.ToolNameSubmitPlan},
		RequiredEditPaths: []string{"a.go"},
	}
	rejected := workspace.ToolResult{
		Tool:    "tool_parse",
		Summary: "Malformed tool request rejected",
		Error:   "decode submit_plan tool request",
		Output:  `{"tool":"submit_plan","edits":"[]"}`,
	}
	results := []workspace.ToolResult{
		{Tool: "read_file", Summary: "Read f1 a.go lines 1-10 (total lines: 10)", Output: "1:package a\n"},
		rejected,
	}
	req := workspace.ToolRequest{Tool: workspace.ToolNameSubmitPlan}
	contract := deriveTurnPhaseContract(TurnPhaseContractInput{
		ContractID:        "contract-malformed-submit",
		Brief:             brief,
		Results:           results,
		LastRequest:       req,
		LastResult:        rejected,
		BaseAllowedTools:  brief.AllowedTools,
		TextualToolParser: true,
	})
	if contract.PhaseID != turnPhaseMalformedSubmitPlanRecovery {
		t.Fatalf("phase = %q, want malformed recovery", contract.PhaseID)
	}

	state, ok := DerivePlanExecuteRecoveryState(brief, results, PlanExecutePlanningTransport{TextualToolParser: true}, contract, req, rejected, 0)
	if !ok {
		t.Fatal("expected malformed submit-plan recovery state")
	}
	if state.Surface != PlanExecuteRecoverySurfaceSubmitReady || state.PhaseID != turnPhaseMalformedSubmitPlanRecovery {
		t.Fatalf("surface/phase = %q/%q, want submit-ready malformed projection: %#v", state.Surface, state.PhaseID, state)
	}
	if state.ActionClass != actionSubmitPlan {
		t.Fatalf("malformed textual submit_plan should keep rejected action class submit_plan, got %#v", state)
	}
	if !strings.Contains(state.RecoveryCardProtocolProjectionID, turnPhaseMalformedSubmitPlanRecovery) {
		t.Fatalf("projection should preserve malformed phase: %#v", state)
	}
	if successfulSubmitPlanResultCount(results) != 0 {
		t.Fatalf("malformed submit_plan parse must not count as a plan artifact")
	}
	assertContains(t, state.VisibleSafeAlternatives, actionSubmitPlan)
}

