func reviewRepairPhaseEvidenceObjectiveForTest(lines ...string) string {
	parts := []string{
		"Review the applied plan.",
		"",
		"## Phase Evidence Bundle",
		"",
		"```text",
	}

	parts = append(parts, lines...)
	parts = append(parts, "```")

	return strings.Join(parts, "\n")
}

