func TestActiveSurfaceCopiesInputSlices(t *testing.T) {
	visible := []string{"read_file"}
	hidden := []string{"shell"}

	surface := NewActiveSurface(visible, hidden)
	visible[0] = "shell"
	hidden[0] = "read_file"

	if !surface.AllowsTool("read_file") {
		t.Fatalf("expected copied visible tool to remain allowed: %#v", surface.VisibleTools)
	}
	if !surface.HidesTool("shell") {
		t.Fatalf("expected copied hidden tool to remain hidden: %#v", surface.HiddenTools)
	}
}

func TestActiveSurfaceNormalizesVisibility(t *testing.T) {
	surface := NewActiveSurface(
		[]string{" read_file ", "shell", "read_file", ""},
		[]string{"shell", "shell", ""},
	)

	if surface.AllowsTool("shell") {
		t.Fatalf("hidden tool leaked into visible surface: %#v", surface)
	}
	if len(surface.VisibleTools) != 1 || surface.VisibleTools[0] != "read_file" {
		t.Fatalf("VisibleTools = %#v, want read_file", surface.VisibleTools)
	}
	if len(surface.HiddenTools) != 1 || surface.HiddenTools[0] != "shell" {
		t.Fatalf("HiddenTools = %#v, want shell", surface.HiddenTools)
	}
}

func TestActiveSurfaceHideAndReleaseByOwner(t *testing.T) {
	surface := NewActiveSurface([]string{"read_file", "shell"}, nil)

	surface.Hide(OwnerLoopPolicy, "read_file")
	surface.Hide(OwnerSourceGrounding, "read_file")
	surface.Release(OwnerLoopPolicy)

	if surface.HiddenByOwner(OwnerLoopPolicy, "read_file") {
		t.Fatalf("loop owner should be released: %#v", surface)
	}
	if !surface.HiddenByOwner(OwnerSourceGrounding, "read_file") {
		t.Fatalf("source-grounding owner should still hold read_file: %#v", surface)
	}
	if !surface.HidesTool("read_file") {
		t.Fatalf("read_file should remain hidden while another owner holds it: %#v", surface)
	}
	if surface.AllowsTool("read_file") {
		t.Fatalf("hidden read_file leaked into visible tools: %#v", surface.VisibleTools)
	}

	surface.Release(OwnerSourceGrounding)
	surface.SetVisibleTools([]string{"read_file", "shell"})
	if surface.HidesTool("read_file") {
		t.Fatalf("read_file should be released: %#v", surface.HiddenTools)
	}
	if !surface.AllowsTool("read_file") {
		t.Fatalf("read_file should be visible after release: %#v", surface.VisibleTools)
	}
}

func TestActiveSurfaceSetVisibleFiltersHidden(t *testing.T) {
	surface := NewActiveSurface(nil, nil)
	surface.Hide(OwnerLoopPolicy, "shell")
	surface.SetVisibleTools([]string{"read_file", "shell"})

	if surface.AllowsTool("shell") {
		t.Fatalf("hidden shell leaked into visible surface: %#v", surface.VisibleTools)
	}
	if !surface.AllowsTool("read_file") {
		t.Fatalf("read_file should remain visible: %#v", surface.VisibleTools)
	}
}

func TestActiveSurfaceHideExcept(t *testing.T) {
	surface := NewActiveSurface([]string{"read_file", "edit_file", "shell"}, nil)
	surface.HideExcept(OwnerImplementationWriteOnly, surface.VisibleTools, func(tool string) bool {
		return tool == "edit_file"
	})

	if !surface.AllowsTool("edit_file") {
		t.Fatalf("edit_file should remain visible: %#v", surface.VisibleTools)
	}
	if surface.AllowsTool("read_file") || surface.AllowsTool("shell") {
		t.Fatalf("non-write tools should be hidden: %#v", surface.VisibleTools)
	}
}

